/**
 * A signature AgentMail adds to every message the inbox sends: send,
 * reply, reply-all, forward, and drafts, including scheduled ones. It goes
 * right after your content, above any quoted or forwarded message. It is
 * not added again when your body already contains it, and it is not added
 * to Visa TAP messages.
 */
export interface InboxSignature {
    /** Signature for the plain-text part. At most 1,000 characters. */
    text: string;
    /**
     * Signature for the HTML part. At most 4,000 characters, so link images
     * by URL rather than embedding them. When omitted, the HTML part gets
     * `text` with its line breaks.
     */
    html?: string;
}
